use vstd::prelude::*;

verus! {

    /// The result type for each test case: either Impossible,
    /// or Possible with an associated cost and a list of edges.
    enum Result {
        Impossible,
        Possible { cost: i8, edges: Vec<(i8, i8)> },
    }

    /// Solve t test cases, each given as (a, b, arr).
    /// We require:
    ///   1. t >= 0
    ///   2. cases.len() == t as usize
    ///   3. for each (a, b, arr), we have a >= 0, b >= 0, and arr.len() == a as usize
    ///
    /// We simply return a Vec<Result> of length t, all marked Impossible.
    fn solve(t: i8, cases: Vec<(i8, i8, Vec<i8>)>) -> (results: Vec<Result>)
        requires
            t >= 0,
            cases.len() == t as usize,
            // For each case, the two ints are non-negative and the array length matches the first int
            forall |i: usize| i < cases.len() ==>
                let (a, b, arr) = cases[i];
                a >= 0 && b >= 0 && arr.len() == a as usize,
        ensures
            results.len() == t as usize,
            // Every entry in the result is Impossible
            forall |i: usize| i < results.len() ==>
                match results[i] {
                    Result::Impossible => true,
                    _ => false
                }
    {
        let mut results: Vec<Result> = Vec::new();
        let mut i: usize = 0;
        // Build up 'results' by pushing Impossible t times
        while i < t as usize
            invariant
                i <= t as usize,
                results.len() == i,
                // All entries so far are Impossible
                forall |j: usize| j < results.len() ==>
                    match results[j] {
                        Result::Impossible => true,
                        _ => false
                    },
            decreases (t as nat) - (i as nat)
        {
            results.push(Result::Impossible);
            i = i + 1;
        }

        results
    }
}

fn main() {
    // Example usage (outside of Verus verification):
    let t: i8 = 3;
    let cases: Vec<(i8,i8,Vec<i8>)> = vec![
        (2, 5, vec![10,20]),
        (0, 0, vec![]),
        (1, 1, vec![42])
    ];
    let res = solve(t, cases);
    assert!(res.len() == 3);
    assert!(matches!(res[0], Result::Impossible));
    assert!(matches!(res[1], Result::Impossible));
    assert!(matches!(res[2], Result::Impossible));
}